/// The account must have the invited email address; any other account gets 404 invitation_not_found. Rate limited per client address.
pub async fn accept_invitation(configuration: &configuration::Configuration, invitation_token: models::InvitationToken, x_csrf_token: Option<&str>) -> Result<models::Workspace, Error<AcceptInvitationError>> {
    // add a prefix to parameters to efficiently prevent name collisions
    let p_body_invitation_token = invitation_token;
    let p_header_x_csrf_token = x_csrf_token;

    let uri_str = format!("{}/api/v1/invitations/accept", configuration.base_path);
    let mut req_builder = configuration.client.request(reqwest::Method::POST, &uri_str);

    if let Some(ref user_agent) = configuration.user_agent {
        req_builder = req_builder.header(reqwest::header::USER_AGENT, user_agent.clone());
    }
    if let Some(param_value) = p_header_x_csrf_token {
        req_builder = req_builder.header("X-CSRF-Token", param_value.to_string());
    }
    if let Some(ref token) = configuration.bearer_access_token {
        req_builder = req_builder.bearer_auth(token.to_owned());
    };
    req_builder = req_builder.json(&p_body_invitation_token);

    let req = req_builder.build()?;
    let resp = configuration.client.execute(req).await?;

    let status = resp.status();
    let content_type = resp
        .headers()
        .get("content-type")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("application/octet-stream");
    let content_type = super::ContentType::from(content_type);

    if !status.is_client_error() && !status.is_server_error() {
        let content = resp.text().await?;
        match content_type {
            ContentType::Json => serde_json::from_str(&content).map_err(Error::from),
            ContentType::Text => return Err(Error::from(serde_json::Error::custom("Received `text/plain` content type response that cannot be converted to `models::Workspace`"))),
            ContentType::Unsupported(unknown_type) => return Err(Error::from(serde_json::Error::custom(format!("Received `{unknown_type}` content type response that cannot be converted to `models::Workspace`")))),
        }
    } else {
        let content = resp.text().await?;
        let entity: Option<AcceptInvitationError> = serde_json::from_str(&content).ok();
        Err(Error::ResponseError(ResponseContent { status, content, entity }))
    }
}

/// Hands the answers, one per question and in order, to a connection of an interactive site that waits for them (ADR-0016). The questions arrive on the event stream as connection.prompt. A prompt that no longer waits, or belongs to another account, is 404 prompt_not_found; a different number of answers is 422 invalid_answers. Answers are never stored or logged.
