/// The body is streamed to a \"<directory>/transferly-<transferId>.part\" file owned by its recorded transfer. An interrupted upload retains that staging file; resume must use the same transferId and its staged size as offset. Existing destinations are replaced only when the adapter and server provide safe replacement; otherwise safe_replace_unsupported preserves the original and the client can save under another name. Unowned legacy \"<path>.part\" files are not adopted automatically.
pub async fn upload_file(configuration: &configuration::Configuration, workspace_id: &str, site_id: &str, path: &str, body: std::path::PathBuf, x_csrf_token: Option<&str>, mode: Option<&str>, offset: Option<i64>, transfer_id: Option<&str>, size: Option<i64>) -> Result<models::RemoteEntry, Error<UploadFileError>> {
    // add a prefix to parameters to efficiently prevent name collisions
    let p_path_workspace_id = workspace_id;
    let p_path_site_id = site_id;
    let p_query_path = path;
    let p_body_body = body;
    let p_header_x_csrf_token = x_csrf_token;
    let p_query_mode = mode;
    let p_query_offset = offset;
    let p_query_transfer_id = transfer_id;
    let p_query_size = size;

    let uri_str = format!("{}/api/v1/workspaces/{workspaceId}/sites/{siteId}/files/content", configuration.base_path, workspaceId=crate::apis::urlencode(p_path_workspace_id), siteId=crate::apis::urlencode(p_path_site_id));
    let mut req_builder = configuration.client.request(reqwest::Method::PUT, &uri_str);

    req_builder = req_builder.query(&[("path", &p_query_path.to_string())]);
    if let Some(ref param_value) = p_query_mode {
        req_builder = req_builder.query(&[("mode", &param_value.to_string())]);
    }
    if let Some(ref param_value) = p_query_offset {
        req_builder = req_builder.query(&[("offset", &param_value.to_string())]);
    }
    if let Some(ref param_value) = p_query_transfer_id {
        req_builder = req_builder.query(&[("transferId", &param_value.to_string())]);
    }
    if let Some(ref param_value) = p_query_size {
        req_builder = req_builder.query(&[("size", &param_value.to_string())]);
    }
    if let Some(ref user_agent) = configuration.user_agent {
        req_builder = req_builder.header(reqwest::header::USER_AGENT, user_agent.clone());
    }
    if let Some(param_value) = p_header_x_csrf_token {
        req_builder = req_builder.header("X-CSRF-Token", param_value.to_string());
    }
    if let Some(ref token) = configuration.bearer_access_token {
        req_builder = req_builder.bearer_auth(token.to_owned());
    };
    let file = TokioFile::open(p_body_body).await?;
    let stream = FramedRead::new(file, BytesCodec::new());
    req_builder = req_builder.body(reqwest::Body::wrap_stream(stream));

    let req = req_builder.build()?;
    let resp = configuration.client.execute(req).await?;

    let status = resp.status();
    let content_type = resp
        .headers()
        .get("content-type")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("application/octet-stream");
    let content_type = super::ContentType::from(content_type);

    if !status.is_client_error() && !status.is_server_error() {
        let content = resp.text().await?;
        match content_type {
            ContentType::Json => serde_json::from_str(&content).map_err(Error::from),
            ContentType::Text => return Err(Error::from(serde_json::Error::custom("Received `text/plain` content type response that cannot be converted to `models::RemoteEntry`"))),
            ContentType::Unsupported(unknown_type) => return Err(Error::from(serde_json::Error::custom(format!("Received `{unknown_type}` content type response that cannot be converted to `models::RemoteEntry`")))),
        }
    } else {
        let content = resp.text().await?;
        let entity: Option<UploadFileError> = serde_json::from_str(&content).ok();
        Err(Error::ResponseError(ResponseContent { status, content, entity }))
    }
}

